queries.sphinxql:
create table jieba_test_accurate (title text) morphology='jieba_chinese' jieba_mode='accurate' charset_table='cont,non_cont';
insert into jieba_test_accurate values(1,'土風舞班');
create table jieba_test_accurate2 (title text) morphology='jieba_chinese' jieba_mode='accurate' charset_table='cont,non_cont';
insert into jieba_test_accurate2 values(1,'土風舞班');
create table jieba_test_accurate_hmm0 (title text) morphology='jieba_chinese' jieba_mode='accurate' jieba_hmm=0 charset_table='cont,non_cont';
insert into jieba_test_accurate_hmm0 values(1,'土風舞班');
create table jieba_test_full (title text) morphology='jieba_chinese' jieba_mode='full' charset_table='cont,non_cont';
insert into jieba_test_full values(1,'土風舞班');
select * from jieba_test_full where match('土風') option jieba_mode='accurate';
select * from jieba_test_accurate where match('土風') option jieba_mode='accurate';
select * from jieba_test_accurate2 where match('土風') option jieba_mode='accurate';
select * from jieba_test_accurate_hmm0 where match('土風') option jieba_mode='accurate';
CALL KEYWORDS ( '文山區長青學苑則有個十分特別的「英文歌唱班」，test', 'jieba_test_accurate', 'accurate' as jieba_mode );
CALL KEYWORDS ( '文山區長青學苑則有個十分特別的「英文歌唱班」，test', 'jieba_test_accurate', 'full' as jieba_mode );
drop table jieba_test_accurate;
drop table jieba_test_accurate2;
drop table jieba_test_accurate_hmm0;
drop table jieba_test_full;

create table jieba_custom_dict (title text) morphology='jieba_chinese' charset_table='cont,non_cont' jieba_user_dict_path='/jieba_user_dict.txt';
insert into jieba_custom_dict values(1,'土風舞班');
flush ramchunk jieba_custom_dict;
select * from jieba_custom_dict;
drop table jieba_custom_dict;


CREATE TABLE gh5140 (`中文列` text, title text, `mixed中文field` text) engine='rowwise' charset_table='non_cont,chinese' morphology='jieba_chinese';
INSERT INTO gh5140 (id, `中文列`, title, `mixed中文field`) VALUES (1, '橙黄苹果 苹果 needle', 'other', 'other'), (2, 'other', '橙黄苹果 苹果 needle', 'other'), (3, 'other', 'other', '橙黄苹果 苹果 needle');
SELECT id AS unscoped FROM gh5140 WHERE MATCH('苹果') ORDER BY id ASC;
SELECT id AS single_field FROM gh5140 WHERE MATCH('@中文列 苹果') ORDER BY id ASC;
SELECT id AS ascii_field FROM gh5140 WHERE MATCH('@title needle') ORDER BY id ASC;
SELECT id AS mixed_field FROM gh5140 WHERE MATCH('@mixed中文field needle') ORDER BY id ASC;
SELECT id AS field_list FROM gh5140 WHERE MATCH('@(中文列,title) needle') ORDER BY id ASC;
SELECT id AS excluded_field FROM gh5140 WHERE MATCH('@!中文列 needle') ORDER BY id ASC;
SELECT id AS excluded_list FROM gh5140 WHERE MATCH('@!(中文列,title) needle') ORDER BY id ASC;
SELECT id AS position_limit FROM gh5140 WHERE MATCH('@中文列[10] needle') ORDER BY id ASC;
SELECT COUNT(*) AS position_rejected FROM gh5140 WHERE MATCH('@中文列[1] needle');
SELECT id AS all_fields FROM gh5140 WHERE MATCH('@* needle') ORDER BY id ASC;
SELECT id AS quoted_text FROM gh5140 WHERE MATCH('@中文列 "苹果 needle"') ORDER BY id ASC;
DROP TABLE gh5140;
